// Cvss3Scores returns CVSS V3 Score
func (v VulnInfo) Cvss3Scores(myFamily ...string) (values []CveContentCvss) {
	family := ""
	if len(myFamily) > 0 {
		family = myFamily[0]
	}
	familyTypes := CveContentTypes(GetCveContentTypes(family))
	directTypes := append(CveContentTypes{}, familyTypes...)
	directTypes = append(directTypes, CveContentTypes{RedHatAPI, RedHat, SUSE, Nvd, Jvn}.Except(directTypes...)...)
	roughTypes := append(CveContentTypes{}, familyTypes...)
	roughTypes = append(roughTypes, CveContentTypes{Debian, DebianSecurityTracker, Ubuntu, UbuntuAPI, Amazon, Trivy, GitHub, WpScan}.Except(roughTypes...)...)
	roughTypeSet := make(map[CveContentType]bool, len(roughTypes))
	for _, ctype := range roughTypes {
		roughTypeSet[ctype] = true
	}
	directTypeSet := make(map[CveContentType]bool, len(directTypes))
	for _, ctype := range directTypes {
		directTypeSet[ctype] = true
	}

	for _, ctype := range directTypes {
		if conts, found := v.CveContents[ctype]; found {
			for _, cont := range conts {
				if roughTypeSet[ctype] && cont.Cvss3Score == 0 {
					continue
				}
				if cont.Cvss3Score == 0 && cont.Cvss3Severity == "" {
					continue
				}
				// https://nvd.nist.gov/vuln-metrics/cvss
				values = append(values, CveContentCvss{
					Type: ctype,
					Value: Cvss{
						Type:     CVSS3,
						Score:    cont.Cvss3Score,
						Vector:   cont.Cvss3Vector,
						Severity: strings.ToUpper(cont.Cvss3Severity),
					},
				})
			}
		}
	}

	for _, ctype := range roughTypes {
		if conts, found := v.CveContents[ctype]; found {
			for _, cont := range conts {
				if cont.Cvss3Severity != "" && !(directTypeSet[ctype] && cont.Cvss3Score != 0) {
					values = append(values, CveContentCvss{
						Type: ctype,
						Value: Cvss{
							Type:                 CVSS3,
							Score:                severityToCvssScoreRoughly(cont.Cvss3Severity),
							CalculatedBySeverity: true,
							Severity:             strings.ToUpper(cont.Cvss3Severity),
						},
					})
				}
			}
		}
	}

	// Memo: Only RedHat, SUSE, Oracle and Amazon has severity data in advisory.
	for _, adv := range v.DistroAdvisories {
		if adv.Severity != "" {
			score := severityToCvssScoreRoughly(adv.Severity)
			values = append(values, CveContentCvss{
				Type: "Vendor",
				Value: Cvss{
					Type:                 CVSS3,
					Score:                score,
					CalculatedBySeverity: true,
					Severity:             strings.ToUpper(adv.Severity),
				},
			})
		}
	}
	return
}

